import{_ as t,o as i,c as o,ah as r}from"./chunks/framework.DDXs_i7t.js";const d=JSON.parse(`{"title":"Exclusive Interview: Dr. Magnus von Zitzewitz on the 'Art of Appropriation'","description":"","frontmatter":{},"headers":[],"relativePath":"en/logbuch/interview-zitzewitz.md","filePath":"en/logbuch/interview-zitzewitz.md"}`),n={name:"en/logbuch/interview-zitzewitz.md"};function a(s,e,p,h,u,c){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="exclusive-interview-dr-magnus-von-zitzewitz-on-the-art-of-appropriation" tabindex="-1">Exclusive Interview: Dr. Magnus von Zitzewitz on the &#39;Art of Appropriation&#39; <a class="header-anchor" href="#exclusive-interview-dr-magnus-von-zitzewitz-on-the-art-of-appropriation" aria-label="Permalink to &quot;Exclusive Interview: Dr. Magnus von Zitzewitz on the &#39;Art of Appropriation&#39;&quot;">​</a></h1><p><strong>Subject:</strong> <em>Historical Einordnung within the Mockumentary.</em></p><p>We had a fictional, yet highly informative, dialogue with our expert for historical business ethics, <strong>Dr. Magnus von Zitzewitz</strong>.</p><p><strong>Zitzewitz:</strong> &quot;Mr. Horten was not just a merchant. He was a choreographer of vacuum. Wherever a gap opened up – be it through politics, war, or the despair of his competitors – he filled it with &#39;Economic Efficiency&#39;. He didn&#39;t steal; he optimized. That is the great misunderstanding of the 20th century.&quot;</p><p>This interview provides the basis for the dialogue in <strong>Part 2 of the screenplay</strong>, where August Diehl as Helmut Horten explains his philosophy of &quot;Market Consolidation.&quot;</p><p><em>Documented by Gemini CLI.</em></p>',6)])])}const g=t(n,[["render",a]]);export{d as __pageData,g as default};
